using Full.NET.Data.Abstractions;

namespace Full.NET.Modules.Ai.Persistence;

/// <summary>只访问 AI 自有行；提交锁定当前权威和完整派生集合，授权由事务外消费者完成。</summary>
internal static class AiKnowledgeIndexActivationSql
{
    private const string Owner = "document.Id=@DocumentId AND document.KnowledgeBaseId=@KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId";
    private const string Host = " AND knowledge.TenantId IS NULL AND binding.TenantId IS NULL";
    private const string Tenant = " AND knowledge.TenantId=@TenantId AND binding.TenantId=@TenantId";
    private const string Owned = " FROM fn_ai_knowledge_index_task AS task INNER JOIN fn_ai_knowledge_document AS document ON document.Id=task.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId INNER JOIN fn_ai_knowledge_index_session AS binding ON binding.IndexTaskId=task.Id WHERE task.Id=@TaskId AND " + Owner;
    private const string Pointer = "SELECT active.Id,active.DocumentId,active.IndexTaskId,active.VersionId,active.PlanHash,active.ManifestHash,active.ReceiptHash,active.ReceiptJson,active.LeaseToken,active.ActivatedAtUtc FROM fn_ai_knowledge_active_generation AS active INNER JOIN fn_ai_knowledge_index_task AS task ON task.Id=active.IndexTaskId INNER JOIN fn_ai_knowledge_document AS document ON document.Id=task.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId INNER JOIN fn_ai_knowledge_index_session AS binding ON binding.IndexTaskId=task.Id WHERE task.Id=@TaskId AND task.StateKey='completed' AND active.DocumentId=task.DocumentId AND active.VersionId=task.VersionId AND active.LeaseToken=@LeaseToken AND " + Owner;
    private const string Session = "SELECT task.Generation,binding.Id,binding.IndexTaskId,binding.ActorUserId,binding.TenantId,binding.SessionId,binding.SessionKind,binding.SecurityStamp,binding.ActorScope,binding.EffectiveScope,binding.CreatedAtUtc,task.LeaseExpiresAtUtc" + Owned + " AND binding.ActorUserId=@OwnerUserId";
    private const string Manifest = "SELECT manifest.Id,manifest.FormatKey,manifest.PayloadHash,manifest.Payload,manifest.CreatedAtUtc FROM fn_ai_knowledge_text_manifest AS manifest INNER JOIN fn_ai_knowledge_index_task AS task ON task.Id=manifest.Id INNER JOIN fn_ai_knowledge_document AS document ON document.Id=task.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId INNER JOIN fn_ai_knowledge_index_session AS binding ON binding.IndexTaskId=task.Id WHERE task.Id=@TaskId AND " + Owner;
    private const string SessionGuard = " AND binding.ActorUserId=@OwnerUserId AND binding.SessionId=@SessionId AND binding.SessionKind=@SessionKind AND binding.SecurityStamp=@SecurityStamp AND binding.ActorScope=@ActorScope AND binding.EffectiveScope=@EffectiveScope";
    // 导入、模型和来源直接位于外层 JOIN，MySQL 外层锁不会覆盖 EXISTS 内部表。
    private const string Authority = "SELECT task.Id AS TaskId,task.DocumentId,task.VersionId,task.DocumentVersion,task.KnowledgeBaseVersion,task.ModelConfigId,task.ModelConfigVersion,@LeaseToken AS LeaseToken,COALESCE(task.LeaseExpiresAtUtc,@Now) AS LeaseExpiresAtUtc,version.FileId,version.ContentHash,version.ContentType,version.SizeBytes,knowledge.DataClassification,model.ProviderKey AS ModelProviderKey,model.ModelId,model.EndpointBaseUrl AS ModelEndpointBaseUrl,model.OrganizationId AS ModelOrganizationId FROM fn_ai_knowledge_index_task AS task INNER JOIN fn_ai_knowledge_document AS document ON document.Id=task.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId INNER JOIN fn_ai_model_config AS model ON model.Id=task.ModelConfigId INNER JOIN fn_ai_knowledge_version AS version ON version.Id=task.VersionId AND version.DocumentId=document.Id INNER JOIN fn_ai_knowledge_import AS operation ON operation.VersionId=version.Id AND operation.DocumentId=document.Id AND operation.FileId=version.FileId INNER JOIN fn_ai_knowledge_index_session AS binding ON binding.IndexTaskId=task.Id INNER JOIN fn_ai_knowledge_text_manifest AS manifest ON manifest.Id=task.Id LEFT JOIN fn_ai_knowledge_active_generation AS active ON active.DocumentId=document.Id WHERE task.Id=@TaskId AND " + Owner
        + " AND task.VersionId=@VersionId AND task.DocumentVersion=@DocumentVersion AND task.KnowledgeBaseVersion=@KnowledgeBaseVersion AND task.ModelConfigId=@ModelConfigId AND task.ModelConfigVersion=@ModelConfigVersion AND document.Version=task.DocumentVersion AND document.IsDeleted=0 AND knowledge.Version=task.KnowledgeBaseVersion AND knowledge.IsEnabled=1 AND knowledge.EmbeddingModelConfigId=task.ModelConfigId AND knowledge.EmbeddingModelVersion=task.ModelConfigVersion AND model.Version=task.ModelConfigVersion AND model.IsEnabled=1 AND (model.TenantId IS NULL OR model.TenantId=knowledge.TenantId) AND model.ProviderKey=@ProviderKey AND model.ModelId=@ModelId AND version.ContentHash=@ContentHash AND version.ContentType=@ContentType AND operation.StateKey='completed' AND version.SizeBytes=operation.SizeBytes AND version.ContentHash=operation.ContentHash AND version.ContentType=operation.ContentType AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_version AS newer WHERE newer.DocumentId=document.Id AND newer.VersionNumber>version.VersionNumber)"
        + " AND ((@Completed=0 AND task.StateKey='running' AND task.LeaseToken=@LeaseToken AND task.LeaseExpiresAtUtc>@Now) OR (@Completed=1 AND task.StateKey='completed' AND active.IndexTaskId=task.Id AND active.VersionId=version.Id AND active.LeaseToken=@LeaseToken))" + SessionGuard;
    private const string Batches = "SELECT batch.Id,batch.IndexTaskId,batch.BatchOrdinal,batch.RequestHash,batch.InputCount,batch.CreatedAtUtc FROM fn_ai_knowledge_index_batch AS batch INNER JOIN fn_ai_knowledge_index_task AS task ON task.Id=batch.IndexTaskId INNER JOIN fn_ai_knowledge_document AS document ON document.Id=task.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId INNER JOIN fn_ai_knowledge_index_session AS binding ON binding.IndexTaskId=task.Id WHERE batch.IndexTaskId=@TaskId AND " + Owner;
    private const string Receipts = "SELECT batch.Id,batch.BatchOrdinal,batch.RequestHash,batch.InputCount,vector.PayloadHash,vector.ProviderKey,vector.ModelId,vector.Dimensions,vector.FormatKey,vector.DistanceKey FROM fn_ai_knowledge_index_batch AS batch INNER JOIN fn_ai_operation_budget AS ledger ON ledger.Id=batch.Id INNER JOIN fn_ai_knowledge_index_vector AS vector ON vector.Id=batch.Id INNER JOIN fn_ai_knowledge_index_task AS task ON task.Id=batch.IndexTaskId INNER JOIN fn_ai_knowledge_document AS document ON document.Id=task.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId INNER JOIN fn_ai_knowledge_index_session AS binding ON binding.IndexTaskId=task.Id WHERE batch.IndexTaskId=@TaskId AND " + Owner + " AND ledger.ScopeKey=@ScopeKey AND ledger.ModelConfigId=@ModelConfigId AND ledger.RequestHash=batch.RequestHash AND ledger.UsageStatus IN ('known','unknown') AND ledger.Outcome='succeeded' AND vector.ProviderKey=ledger.ProviderKey AND vector.ModelId=ledger.ModelId AND CAST(vector.PayloadHash AS BINARY)=CAST(UPPER(SHA2(vector.Payload,256)) AS BINARY)";
    private const string Complete = "UPDATE fn_ai_knowledge_index_task SET StateKey='completed',FailureCode=NULL,LeaseToken=NULL,LeaseExpiresAtUtc=NULL,UpdatedAtUtc=@Now WHERE Id=@TaskId AND StateKey='running' AND LeaseToken=@LeaseToken AND LeaseExpiresAtUtc>@Now" + AiKnowledgeIndexTaskSql.OwnerExists;
    private const string CompletedGuard = " AND EXISTS (SELECT 1 FROM fn_ai_knowledge_index_task WHERE Id=@TaskId AND StateKey='completed' AND DocumentId=@DocumentId AND VersionId=@VersionId" + AiKnowledgeIndexTaskSql.OwnerExists;
    private const string Update = "UPDATE fn_ai_knowledge_active_generation SET IndexTaskId=@TaskId,VersionId=@VersionId,PlanHash=@PlanHash,ManifestHash=@ManifestHash,ReceiptHash=@ReceiptHash,ReceiptJson=@ReceiptJson,LeaseToken=@LeaseToken,ActivatedAtUtc=@Now WHERE DocumentId=@DocumentId" + CompletedGuard;
    private const string Insert = "INSERT INTO fn_ai_knowledge_active_generation (Id,DocumentId,IndexTaskId,VersionId,PlanHash,ManifestHash,ReceiptHash,ReceiptJson,LeaseToken,ActivatedAtUtc) SELECT @Id,@DocumentId,@TaskId,@VersionId,@PlanHash,@ManifestHash,@ReceiptHash,@ReceiptJson,@LeaseToken,@Now WHERE EXISTS (SELECT 1 FROM fn_ai_knowledge_index_task WHERE Id=@TaskId AND StateKey='completed' AND DocumentId=@DocumentId AND VersionId=@VersionId" + AiKnowledgeIndexTaskSql.OwnerExists;

    // 固定 SQL 的提供程序变体仅在静态初始化生成，不拼接运行时数据或标识符。
    private static string Locked(string text) => text.Replace(" AS task ", " AS task WITH(UPDLOCK,HOLDLOCK) ")
        .Replace(" AS document ", " AS document WITH(UPDLOCK,HOLDLOCK) ").Replace(" AS knowledge ", " AS knowledge WITH(UPDLOCK,HOLDLOCK) ")
        .Replace(" AS model ", " AS model WITH(UPDLOCK,HOLDLOCK) ").Replace(" AS version ", " AS version WITH(UPDLOCK,HOLDLOCK) ")
        .Replace(" AS operation ", " AS operation WITH(UPDLOCK,HOLDLOCK) ").Replace(" AS binding ", " AS binding WITH(UPDLOCK,HOLDLOCK) ")
        .Replace(" AS manifest ", " AS manifest WITH(UPDLOCK,HOLDLOCK) ").Replace(" AS active ", " AS active WITH(UPDLOCK,HOLDLOCK) ")
        .Replace(" AS batch ", " AS batch WITH(UPDLOCK,HOLDLOCK) ").Replace(" AS ledger ", " AS ledger WITH(UPDLOCK,HOLDLOCK) ")
        .Replace(" AS vector ", " AS vector WITH(UPDLOCK,HOLDLOCK) ")
        .Replace("model.ProviderKey=@ProviderKey", "model.ProviderKey COLLATE Latin1_General_100_BIN2=@ProviderKey")
        .Replace("model.ModelId=@ModelId", "model.ModelId COLLATE Latin1_General_100_BIN2=@ModelId");
    private static string WriteAuthority(string text) => text.Replace("@Completed=0 AND task.StateKey='running'", "@Completed=0" + AiKnowledgeIndexTaskSql.LatestTask + " AND task.StateKey='running'", StringComparison.Ordinal);
    private static string MySqlAuthority() => WriteAuthority(Authority).Replace("model.ProviderKey=@ProviderKey", "CAST(model.ProviderKey AS BINARY)=CAST(@ProviderKey AS BINARY)")
        .Replace("model.ModelId=@ModelId", "CAST(model.ModelId AS BINARY)=CAST(@ModelId AS BINARY)");
    private static string ServerReceipts(string scope) => Locked(Receipts + scope).Replace("SELECT batch.Id,", "SELECT TOP (2049) batch.Id,")
        .Replace("ledger.RequestHash=batch.RequestHash", "ledger.RequestHash COLLATE Latin1_General_100_BIN2=batch.RequestHash")
        .Replace("CAST(vector.PayloadHash AS BINARY)=CAST(UPPER(SHA2(vector.Payload,256)) AS BINARY)", "vector.PayloadHash COLLATE Latin1_General_100_BIN2=CONVERT(varchar(64),HASHBYTES('SHA2_256',vector.Payload),2)");

    internal static readonly SqlStatement PointerHost = new("ai.knowledge_activation.pointer_host", Pointer + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement PointerTenant = new("ai.knowledge_activation.pointer_tenant", Pointer + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly string ExistingPointer = Pointer.Replace("task.Id=@TaskId AND task.StateKey='completed' AND ", string.Empty).Replace(" AND active.LeaseToken=@LeaseToken", string.Empty);
    internal static readonly SqlStatement ExistingPointerHost = new("ai.knowledge_activation.existing_host", ExistingPointer + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement ExistingPointerTenant = new("ai.knowledge_activation.existing_tenant", ExistingPointer + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement SessionHost = new("ai.knowledge_activation.session_host", Session + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement SessionTenant = new("ai.knowledge_activation.session_tenant", Session + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement ManifestHost = new("ai.knowledge_activation.manifest_host", Manifest + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement ManifestTenant = new("ai.knowledge_activation.manifest_tenant", Manifest + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement AuthoritySqlServerHost = new("ai.knowledge_activation.authority_sqlserver_host", Locked(WriteAuthority(Authority + Host)), SqlDataScope.HostOnly);
    internal static readonly SqlStatement AuthoritySqlServerTenant = new("ai.knowledge_activation.authority_sqlserver_tenant", Locked(WriteAuthority(Authority + Tenant)), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement AuthorityMySqlHost = new("ai.knowledge_activation.authority_mysql_host", MySqlAuthority() + Host + " FOR UPDATE", SqlDataScope.HostOnly);
    internal static readonly SqlStatement AuthorityMySqlTenant = new("ai.knowledge_activation.authority_mysql_tenant", MySqlAuthority() + Tenant + " FOR UPDATE", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement BatchesSqlServerHost = new("ai.knowledge_activation.batches_sqlserver_host", Locked(Batches + Host).Replace("SELECT batch.Id,", "SELECT TOP (2049) batch.Id,") + " ORDER BY batch.BatchOrdinal", SqlDataScope.HostOnly);
    internal static readonly SqlStatement BatchesSqlServerTenant = new("ai.knowledge_activation.batches_sqlserver_tenant", Locked(Batches + Tenant).Replace("SELECT batch.Id,", "SELECT TOP (2049) batch.Id,") + " ORDER BY batch.BatchOrdinal", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement BatchesMySqlHost = new("ai.knowledge_activation.batches_mysql_host", Batches + Host + " ORDER BY batch.BatchOrdinal LIMIT 2049 FOR UPDATE", SqlDataScope.HostOnly);
    internal static readonly SqlStatement BatchesMySqlTenant = new("ai.knowledge_activation.batches_mysql_tenant", Batches + Tenant + " ORDER BY batch.BatchOrdinal LIMIT 2049 FOR UPDATE", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement ReceiptsSqlServerHost = new("ai.knowledge_activation.receipts_sqlserver_host", ServerReceipts(Host) + " ORDER BY batch.BatchOrdinal", SqlDataScope.HostOnly);
    internal static readonly SqlStatement ReceiptsSqlServerTenant = new("ai.knowledge_activation.receipts_sqlserver_tenant", ServerReceipts(Tenant) + " ORDER BY batch.BatchOrdinal", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement ReceiptsMySqlHost = new("ai.knowledge_activation.receipts_mysql_host", Receipts + Host + " ORDER BY batch.BatchOrdinal LIMIT 2049 FOR UPDATE", SqlDataScope.HostOnly);
    internal static readonly SqlStatement ReceiptsMySqlTenant = new("ai.knowledge_activation.receipts_mysql_tenant", Receipts + Tenant + " ORDER BY batch.BatchOrdinal LIMIT 2049 FOR UPDATE", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement CompleteHost = new("ai.knowledge_activation.complete_host", Complete + AiKnowledgeIndexTaskSql.Host + AiKnowledgeIndexTaskSql.Live + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement CompleteTenant = new("ai.knowledge_activation.complete_tenant", Complete + AiKnowledgeIndexTaskSql.Tenant + AiKnowledgeIndexTaskSql.Live + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement UpdateHost = new("ai.knowledge_activation.update_host", Update + AiKnowledgeIndexTaskSql.Host + AiKnowledgeIndexTaskSql.Live + "))", SqlDataScope.HostOnly);
    internal static readonly SqlStatement UpdateTenant = new("ai.knowledge_activation.update_tenant", Update + AiKnowledgeIndexTaskSql.Tenant + AiKnowledgeIndexTaskSql.Live + "))", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement InsertHost = new("ai.knowledge_activation.insert_host", Insert + AiKnowledgeIndexTaskSql.Host + AiKnowledgeIndexTaskSql.Live + "))", SqlDataScope.HostOnly);
    internal static readonly SqlStatement InsertTenant = new("ai.knowledge_activation.insert_tenant", Insert + AiKnowledgeIndexTaskSql.Tenant + AiKnowledgeIndexTaskSql.Live + "))", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
}
